<?php
if (!defined('ABSPATH')) { exit; }
final class KornSW_ATH_Admin {
    public static function register_hooks(){add_action('admin_menu',array(__CLASS__,'menu'));add_action('admin_enqueue_scripts',array(__CLASS__,'assets'));add_action('admin_post_kornsw_ath_save_settings',array(__CLASS__,'save'));add_filter('plugin_action_links_'.plugin_basename(KORNSW_ATH_FILE),array(__CLASS__,'plugin_links'));}
    public static function menu(){add_options_page('AuthTokenHandling (KornSW)','AuthTokenHandling (KornSW)','manage_options','kornsw-authtokenhandling',array(__CLASS__,'page'));}
    public static function plugin_links($links){array_unshift($links,'<a href="'.esc_url(admin_url('options-general.php?page=kornsw-authtokenhandling')).'">Einstellungen</a>');return $links;}
    public static function assets($hook){if($hook!=='settings_page_kornsw-authtokenhandling')return;wp_enqueue_style('kornsw-ath-admin',KORNSW_ATH_URL.'assets/admin.css',array(),KORNSW_ATH_VERSION);wp_enqueue_script('kornsw-ath-admin',KORNSW_ATH_URL.'assets/admin.js',array(),KORNSW_ATH_VERSION,true);wp_localize_script('kornsw-ath-admin','KornSWATH',array('defaultProfile'=>KornSW_ATH_Config_Repository::create_default_profile()));}
    public static function save(){if(!current_user_can('manage_options'))wp_die('Nicht erlaubt.',403);check_admin_referer('kornsw_ath_save_settings');$json=(string)wp_unslash($_POST['profiles_json']??'[]');$result=KornSW_ATH_Config_Repository::save_profiles_json($json);if(is_wp_error($result)){wp_safe_redirect(add_query_arg(array('page'=>'kornsw-authtokenhandling','ath_error'=>rawurlencode($result->get_error_message())),admin_url('options-general.php')));exit;}update_option(KornSW_ATH_Config_Repository::OPTION_PRIMARY_SOURCE,sanitize_text_field(wp_unslash($_POST['primary_source_uid']??'')),false);update_option(KornSW_ATH_Config_Repository::OPTION_AUTO_ROLE,sanitize_key(wp_unslash($_POST['auto_role']??'subscriber')),false);wp_safe_redirect(add_query_arg(array('page'=>'kornsw-authtokenhandling','updated'=>'true'),admin_url('options-general.php')));exit;}
    public static function page(){if(!current_user_can('manage_options'))return;$json=KornSW_ATH_Config_Repository::get_profiles_json();$profiles=KornSW_ATH_Config_Repository::get_profiles();$primary=KornSW_ATH_Config_Repository::get_primary_source_uid();global $wp_roles;?><div class="wrap kornsw-ath"><h1>KornSW AuthTokenHandling</h1><?php if(isset($_GET['ath_error']))echo '<div class="notice notice-error"><p>'.esc_html(wp_unslash($_GET['ath_error'])).'</p></div>'; ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" id="kornsw-ath-form"><input type="hidden" name="action" value="kornsw_ath_save_settings"><?php wp_nonce_field('kornsw_ath_save_settings'); ?><div class="ath-global"><label><strong>Primary WordPress Session Token Source</strong><select name="primary_source_uid" id="ath-primary"><option value="">Keine – klassische WordPress-Session</option><?php foreach($profiles as $p){echo '<option value="'.esc_attr($p['TokenSourceUid']).'" '.selected($primary,$p['TokenSourceUid'],false).'>'.esc_html($p['DisplayName']??$p['TokenSourceUid']).'</option>';} ?></select></label><label><strong>Standardrolle für Auto-Provisioning</strong><select name="auto_role"><?php wp_dropdown_roles(KornSW_ATH_Config_Repository::get_auto_provision_role()); ?></select></label><p class="description">Administratoren können die Primary-Pflicht pro Sitzung bewusst umgehen, um einen OAuth-bedingten Lockout zu verhindern.</p></div><div class="ath-layout"><aside class="ath-profiles"><div class="ath-sidebar-head"><strong>Token Sources</strong><button type="button" class="button" id="ath-add-profile">+</button></div><div id="ath-profile-list"></div></aside><main class="ath-editor"><div id="ath-no-profile">Profil auswählen oder neu anlegen.</div><div id="ath-profile-editor" hidden><?php self::editor_controls(); ?></div></main></div><h2>Authentifizierungs-JSON-Array</h2><p class="description">Dies ist die führende Konfiguration. Der visuelle Editor manipuliert dieses JSON direkt und erhält unbekannte Felder.</p><textarea name="profiles_json" id="ath-json" rows="24" spellcheck="false"><?php echo esc_textarea($json); ?></textarea><p><button type="button" class="button" id="ath-apply-json">JSON in Editor übernehmen</button> <button type="submit" class="button button-primary">Konfiguration speichern</button></p></form></div><?php }
    private static function editor_controls(){?><div class="ath-profile-header"><label>Name<input type="text" data-outer="DisplayName"></label><label>Token Source UID<input type="text" data-outer="TokenSourceUid" readonly></label><label class="ath-inline"><input type="checkbox" data-outer="Enabled"> Aktiv</label><button type="button" class="button-link-delete" id="ath-delete-profile">Profil entfernen</button></div><nav class="ath-tabs"><button type="button" class="button button-primary" data-tab="issuing">Issuing</button><button type="button" class="button" data-tab="introspection">Introspection</button></nav><section data-panel="issuing"><div class="ath-grid"><label>UI-Typ<select id="ath-issue-ui"><option value="raw">Raw</option><option value="local">Lokal</option><option value="oauth">OAuth</option></select></label><label>IssueMode<select data-config="IssueMode"><option>RAW_INPUT</option><option>HTTP_GET</option><option>LOCAL_BASICAUTH_GENERATION</option><option>LOCAL_JWT_GENERATION</option><option>OAUTH_IMPLICIT_FLOW</option><option>OAUTH_CIBA_CODEGRAND</option><option>OAUTH_CIBA_CODEGRAND_HTTPGETONLY</option></select></label><label data-show="oauth">OAuth Operations Provider<select data-outer="OAuthOperationsProvider"><option value="generic">Generic</option><option value="google">Google</option><option value="github">GitHub</option></select></label><label data-show="oauth">Client ID<input type="text" data-config="ClientId"></label><label data-show="oauth">Client Secret<input type="password" data-config="ClientSecret" autocomplete="new-password"></label><label data-show="oauth generic">Authorization Endpoint<input type="url" data-provider="authorization_endpoint"></label><label data-show="oauth generic">Token Endpoint<input type="url" data-provider="token_endpoint"></label><label data-show="oauth">Scopes<input type="text" data-provider="scopes"></label><label data-show="oauth">Additional Auth Args<input type="text" data-config="AdditionalAuthArgs" placeholder='{"prompt":"login"}'></label><label data-show="oauth">Additional Retrieve Args<input type="text" data-config="AdditionalRetrieveArgs"></label><label data-show="local">JWT Expiration (Minuten)<input type="number" data-config="JwtExpMinutes"></label><label data-show="local">JWT Signing Key<input type="password" data-config="JwtSelfSignKey"></label><label data-show="local">JWT Algorithm<input type="text" data-config="JwtSelfSignAlg"></label><label data-show="raw">RetrieveEndpointUrl<input type="url" data-config="RetrieveEndpointUrl"></label><label data-show="raw">RetrieveEndpointAuthorization<input type="text" data-config="RetrieveEndpointAuthorization"></label></div><div data-show="raw" class="ath-raw-box"><h3>Raw AuthTokenConfig</h3><p class="description">Direkter Editor für das komplette AuthTokenConfig-Objekt dieses Profils.</p><textarea rows="16" id="ath-raw-auth-config"></textarea><button type="button" class="button" id="ath-apply-raw-config">Raw AuthTokenConfig übernehmen</button></div><details><summary>Weitere / kompatible Issuing-Felder</summary><div class="ath-grid"><label>DisplayLabel<input type="text" data-config="DisplayLabel"></label><label>DisplayIconUrl<input type="url" data-config="DisplayIconUrl"></label><label>LocalLogonNameSyntax<input type="text" data-config="LocalLogonNameSyntax"></label><label>LocalLogonNamePersistation<select data-config="LocalLogonNamePersistation"><option>NEVER</option><option>OPT-IN</option><option>OPT-OUT</option><option>ALWAYS</option></select></label><label>LocalLogonNameInputLabel<input type="text" data-config="LocalLogonNameInputLabel"></label><label>LocalLogonPassInputLabel<input type="text" data-config="LocalLogonPassInputLabel"></label><label>LocalLogonSaltDisplayLabel<input type="text" data-config="LocalLogonSaltDisplayLabel"></label><label class="ath-inline"><input type="checkbox" data-config="LocalLogonNameToLower"> LocalLogonNameToLower</label><label class="ath-inline"><input type="checkbox" data-config="AuthEndpointRejectsIframe"> AuthEndpointRejectsIframe</label><label class="ath-inline"><input type="checkbox" data-provider="supports_refresh_token"> Provider unterstützt Refresh Token</label><label class="ath-inline"><input type="checkbox" data-provider="supports_id_token"> Provider unterstützt ID Token</label></div></details></section><section data-panel="introspection" hidden><div class="ath-grid"><label>ValidationMode<select data-config="ValidationMode"><option>IMPLICIT_WHEN_USED</option><option>LOCAL_JWT_VALIDATION</option><option>OAUTH_INTROSPECTION_ENDPOINT</option><option>OAUTH_INTROSPECTION_ENDPOINT_HTTPGETONLY</option><option>GITHUB_VALIDATION_ENDPOINT</option></select></label><label>Provider-interner Validation Cache (Min.)<input type="number" min="0" data-config="ValidationOutcomeCacheMins"></label><label data-validation="local">JWT Validation Key<input type="password" data-config="JwtValidationKey"></label><label data-validation="remote">Validation / Introspection Endpoint<input type="url" data-config="ValidationEndpointUrl"></label><label data-validation="remote">validationEndpointAuthorization<input type="text" data-config="validationEndpointAuthorization"></label><label data-provider-field="generic">UserInfo Endpoint<input type="url" data-provider="userinfo_endpoint"></label><label data-provider-field="generic">Introspection Endpoint<input type="url" data-provider="introspection_endpoint"></label><label class="ath-inline"><input type="checkbox" data-config="ClaimValidationIgnoresCasing"> Claim-Namen casing-unabhängig</label></div></section><details><summary>Claims (JSON)</summary><textarea rows="8" id="ath-claims"></textarea></details><?php }
}
